#define main prior_kernel_main
#include "../round2/kernel.cpp"
#undef main
#include "inherited_reference.hpp"
#include <filesystem>
using P=a2::r4::Policy;
std::shared_ptr<a2::r4::QueryPreferences> preferences(P policy,z3::expr x,int value){auto q=std::make_shared<a2::r4::QueryPreferences>();q->policy=policy;q->reference[a2::HostView{}.identity(x)]=value;q->reference_count=1;q->reference_hash="test_reference";q->hard_hash="test_hard";return q;}
int main(int argc,char** argv){try{
 check(argc==2,"output directory");J evidence=J::array();unsigned projected=0,actual_changes=0,positive=0;
 {z3::context c;auto x=c.int_const("x"),y=c.int_const("y"),b=c.bool_const("b");a2::HostView view;auto q=preferences(P::Coverage,x,0);
  for(auto atom:{x==0,x==10,!(x<=0)||!(x>=0),x+10==10}){a2::Work w;std::string why;auto phase=a2::r4::evaluate_reference_phase(view,atom,*q,w,why);check(phase.has_value(),"defined reference missing");auto m=z3::model(c);auto d=x.decl();auto val=c.int_val(0);m.add_const_interp(d,val);check(*phase==m.eval(atom,false).is_true(),"incorrect exact reference");}
  for(auto atom:{x==y,b,x/2==0}){a2::Work w;std::string why;check(!a2::r4::evaluate_reference_phase(view,atom,*q,w,why),"missing/unsupported reference guessed");}
  a2::Entry zero,ten;zero.rules.push_back({0,true,0,~0ull,2,0});ten.rules.push_back({0,true,10,~10ull,2,0});a2::Work w0,w1;auto e0=a2::r4::score_phase_evidence(zero,w0),e1=a2::r4::score_phase_evidence(ten,w1);check(e0.best()==false&&e0.support[0]==0&&e0.block[1]==1,"avoid direction x=0");check(e1.best()==true&&e1.support[1]==1,"support direction x=10");check(a2::r4::advice_targets(e0,false,true)[0].first==2,"avoid target absent");
  check(a2::r4::advice_identity("zero",false,"avoid_direct_blocker",0,1,true)!=a2::r4::advice_identity("ten",true,"coverage_support",0,1,true),"avoid consumed later support");
  auto dup=ten;dup.rules.push_back(ten.rules[0]);a2::Work wd;check(a2::r4::score_phase_evidence(dup,wd).support[1]==1,"duplicate node bit counted");
  // 2^64 is preserved exactly. No wrap and no completion of the partial model.
  q->reference[view.identity(x)]=a2::Big("18446744073709551616");a2::Work wb;std::string why;check(a2::r4::evaluate_reference_phase(view,x>c.int_val("18446744073709551615"),*q,wb,why)==true,"wide integer truncated");
  evidence.push_back({{"test","exact_partial_reference_support_avoid_and_dedup"},{"passed",true}});
 }
 // Same model traversal, selected values and RNG continuation as frozen host.
 {z3::context c;auto x=c.int_const("rx"),y=c.int_const("ry"),aux=c.int_const("aux"),b=c.bool_const("rb");z3::model m(c);for(auto v:{x,y,aux}){auto d=v.decl();auto value=c.int_val(17);m.add_const_interp(d,value);}auto d=b.decl();auto value=c.bool_val(true);m.add_const_interp(d,value);guided::OriginalDeclarations originals;for(auto v:{x,y,b})originals.emplace(v.decl().id(),v);std::mt19937 a(0),b_rng(0);std::uniform_real_distribution<double> da(0,1),db(0,1);auto ref=guided::collect_inherited_reference(m,originals,a,0.5,da,true);std::vector<unsigned> selected;for(unsigned j=0;j<m.size();++j)if(originals.count(m[j].id())&&m[j].is_const()&&m[j].decl_kind()!=Z3_OP_TRUE&&m[j].decl_kind()!=Z3_OP_FALSE&&db(b_rng)<0.5)selected.push_back(j);check(a==b_rng,"collector changed RNG continuation");check(ref.selected.size()==selected.size(),"collector selection count");for(unsigned i=0;i<selected.size();++i)check(ref.selected[i]["model_index"]==selected[i],"collector traversal");check(ref.values.count(a2::HostView{}.identity(aux))==0,"aux reference included");evidence.push_back({{"test","selection_provenance_rng"},{"selected",ref.selected},{"draws",ref.draws}});}
 // Actual native solver, both natural default and an explicit SMT unit backend.
 for(auto policy:{P::Reference,P::Coverage})for(bool temporary:{false,true})for(unsigned hard=0;hard<3;++hard){
  z3::context c;auto x=c.int_const("x");auto f=(x==0)||(x==10);auto s=temporary?z3::tactic(c,"smt").mk_solver():z3::solver(c);s.add(f);if(hard==1)s.add(x==0);z3::expr_vector asms(c);if(hard==2)asms.push_back(x==0);
  auto idx=std::make_shared<a2::Index>();for(auto value:{0,10}){a2::Work w;auto norm=a2::canonical(a2::HostView{},x==value,w);auto& entry=idx->entries[norm.key];entry.original_exact=norm.exact;entry.rules.push_back({0,!norm.negated,uint64_t(value),~uint64_t(value),2,0});}idx->version=1;auto q=preferences(policy,x,0);q->hard_count=asms.size();idx->preferences=q;auto count=s.assertions().size();install(s,idx,2,45,100+unsigned(policy)*10+temporary*3+hard);check(s.check(asms)==z3::sat,"soft SAT failed");auto st=stats(s);clear(s);auto m=s.get_model();auto value=m.eval(x,true).get_numeral_int();check(value==0||value==10,"illegal soft value");if(hard)check(value==0,"real hard condition was softened");check(s.assertions().size()==count,"soft reference added assertion");if(!hard&&policy==P::Coverage)positive+=value==10;actual_changes+=st["phase_overrides"].get<unsigned>();
  check(st["b_encoded"]==0&&st["b_internalized"]==0&&st["guidance_created_bool_vars"]==0&&st["guidance_added_assertions"]==0&&st["guidance_marked_relevant"]==0,"B or hard guidance side effects");for(auto a:st["actions"]){check(a["actual_var"]==a["native_var"],"variable changed");check(a["decision_id"].get<unsigned>()<=64,"window violated");if(a["preference_source"]=="avoid_direct_blocker")check(a["target_semantics"]=="avoid_known_opposite_not_guaranteed_value","avoid misreported as support");}
  evidence.push_back({{"test","soft_zero_or_ten"},{"policy",unsigned(policy)},{"temporary",temporary},{"hard_kind",hard},{"value",value},{"stats",st}});
 }
 // Two incompatible desired bits, all finite legal projections, and UNSAT.
 for(auto policy:{P::Reference,P::Coverage}){z3::context c;auto x=c.int_const("finite");auto f=x==0||x==1||x==2;guided::AGuidanceBridge bridge(f,unsigned(policy)==1?3:4,60,argv[1]);bridge.commit(bridge.ast.evaluate({{"finite",0}}));bridge.index->preferences=preferences(policy,x,0);z3::solver s(c);s.add(f);for(int value=-1;value<=3;++value){z3::expr_vector hard(c);hard.push_back(x==value);bridge.prepare(s,200+value+1);auto r=s.check(hard);auto st=bridge.end_check(s);check((r==z3::sat)==(value>=0&&value<=2),"projection changed");if(r==z3::sat){check(s.get_model().eval(x,true).get_numeral_int()==value,"wrong finite projection");++projected;}}bridge.prepare(s,210);check(s.check()==z3::sat,"conflicting wishes became hard");bridge.end_check(s);int v=s.get_model().eval(x,true).get_numeral_int();check(v>=0&&v<=2&&v!=3,"joint impossible wish forced");s.add(x==3);bridge.prepare(s,211);check(s.check()==z3::unsat,"UNSAT became SAT");bridge.end_check(s);evidence.push_back({{"test","finite_projection_and_conflicting_wishes"},{"policy",unsigned(policy)},{"value",v}});}
 // Reference has its own window, not the coverage quota; native variable unchanged.
 for(auto policy:{P::Reference,P::Coverage}){z3::context c;z3::solver s=z3::tactic(c,"smt").mk_solver();auto idx=std::make_shared<a2::Index>();auto q=std::make_shared<a2::r4::QueryPreferences>();q->policy=policy;
  for(unsigned i=0;i<90;++i){auto a=c.bool_const(("pa"+std::to_string(i)).c_str()),b=c.bool_const(("pb"+std::to_string(i)).c_str());s.add(a||b);q->reference[a2::HostView{}.identity(a)]=1;q->reference[a2::HostView{}.identity(b)]=1;if(policy==P::Coverage)for(auto atom:{a,b}){a2::Work w;auto norm=a2::canonical(a2::HostView{},atom,w);idx->entries[norm.key].rules.push_back({2*i+unsigned(atom.id()==b.id()),norm.negated,0,1,0,1});}}
  idx->version=1;idx->preferences=q;install(s,idx,2,45,300+unsigned(policy));check(s.check()==z3::sat,"reference window SAT");auto st=stats(s);clear(s);check(st["suggestions"].get<unsigned>()==(policy==P::Coverage?4u:0u),"coverage quota incorrect");check(st["actions"].size()>4&&st["actions"].size()<=64,"reference window policy wrong");for(auto a:st["actions"])check(a["decision_id"].get<unsigned>()<=64,"reference outside window");evidence.push_back({{"test","reference_window_and_independent_quota"},{"policy",unsigned(policy)},{"stats",st}});
 }
 check(actual_changes>0,"no actual S override exercised");
 std::cout<<J({{"passed",true},{"projected_solutions",projected},{"actual_changes",actual_changes},{"zero_or_ten_coverage_hits",positive},{"tests",evidence}}).dump(2)<<'\n';
 }catch(std::exception const& e){std::cerr<<e.what()<<'\n';return 1;}}
